def replace_missing_values(data: List[List[Optional[float]]]) -> List[List[float]]:
    # Check if the data is empty
    if not data or not data[0]:
        return data

    # Determine the number of columns
    num_columns = len(data[0])

    # Initialize a list to store the means of each column
    column_means = [0.0] * num_columns

    # Calculate the mean of each column, excluding None values
    for col in range(num_columns):
        total_sum = 0.0
        count = 0
        for row in data:
            if row[col] is not None:
                total_sum += row[col]
                count += 1
        if count > 0:
            column_means[col] = total_sum / count
        else:
            column_means[col] = 0.0

    # Replace None values with the calculated means
    for row in data:
        for col in range(num_columns):
            if row[col] is None:
                row[col] = column_means[col]

    return data

