def min_difference(n, weights):
    total_weight = sum(weights)

    # Create a DP table where dp[i][j] is True if we can achieve weight j using the first i items
    dp = [[False] * (total_weight + 1) for _ in range(n + 1)]

    # Base case: It's always possible to achieve weight 0 with 0 items
    dp[0][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(total_weight + 1):
            if j >= weights[i - 1]:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - weights[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    # Find the smallest weight that can be achieved
    min_diff = float('inf')
    for j in range(total_weight // 2 + 1):
        if dp[n][j]:
            min_diff = min(min_diff, total_weight - 2 * j)

    return min_diff

