def wordLadderLength(beginWord, endWord, wordList):
    # Convert wordList to a set for O(1) lookups
    wordSet = set(wordList)

    # If endWord is not in the wordList, return 0
    if endWord not in wordSet:
        return 0

    # Initialize the queue with the beginWord and its path length
    queue = [(beginWord, 1)]
    visited = set([beginWord])

    # Build the neighbors dictionary
    neighbors = {}
    for word in wordSet:
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c != word[i]:
                    new_word = word[:i] + c + word[i+1:]
                    if new_word in wordSet:
                        if new_word not in neighbors:
                            neighbors[new_word] = []
                        neighbors[new_word].append(word)

    # Perform BFS
    while queue:
        current_word, path_length = queue.pop(0)

        # If the current word is the endWord, return the path length
        if current_word == endWord:
            return path_length

        # Explore neighbors
        for neighbor in neighbors.get(current_word, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path_length + 1))

    # If no path is found, return 0
    return 0

